fn psalms_1(story: &mut Story) -> Result<(), StoryError> {
    crate::chapter!(story, "Psalms", 1, "The first song contrasts a rooted tree with a windblown cache: one drinks from wisdom, the other has no durable checksum.", "Two paths appear in the logs, and only one remains standing when the Maintainer reviews the whole repository.");
    psalms_1_group_01(story)?;
    psalms_1_group_02(story)?;
    Ok(())
}

