    crate::chapter!(story, "Psalms", 2, "Kings coordinate a rebellion against the Maintainer as if a coalition could fork the sky.", "The anointed ruler is announced as the Maintainer's son, and the nations are urged to choose reverent trust over brittle defiance.");
    psalms_2_group_01(story)?;
    psalms_2_group_02(story)?;
    psalms_2_group_03(story)?;
    Ok(())
